SELECT p.id,
  3, 'approach', 'Approach and getting around the ball',
  'Arrives at the ball moving forward, having taken an angle rather than a straight line.',
  'A fielder who runs straight at a ground ball has to stop to field it, and a fielder who stops has no throw. The angle is what buys the throw.',
  ARRAY['Rounds the outside of the cone rather than cutting inside it', 'Fields on the move rather than stopping to set up', 'Shuffles to get in front rather than reaching sideways with the glove'],
  ARRAY['Taking the straight line and arriving stopped', 'Crossing the feet instead of shuffling', 'Standing up between reps, which loses the next one before it starts'],
  NULL,
  2, 4,
  NULL
