-- stage 4: Reading hops
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  4, 'reading-hops', 'Reading hops',
  'Adjusts to a ball that does not bounce true, and receives the short hop with a soft glove.',
  'On a youth infield most balls take a bad hop. A fielder who can only handle the true bounce is a fielder who makes errors on ordinary ground balls.',
  ARRAY['Glove works through the hop rather than at it', 'Moves to the loose ball rather than reaching for it when the hop beats them', 'Picks short hops cleanly more often than not'],
  ARRAY['Stabbing at the ball as it changes direction', 'Freezing after a bad hop instead of recovering', 'Backing up on an in-between hop rather than moving up or dropping back'],
  NULL,
  2, 5,
  'THIN. No drill in the library exists to teach hop reading for an infielder generally. The three attached each cover part of it — recovery after a bad hop, solo short hops off a wall, and a first-base-framed picking progression — and none of them is a general in-between-hop station. A drill that rolls balls at varied distances so the fielder has to choose to charge or drop back would close this; it is not invented here.'
FROM public.development_pathways p WHERE p.slug = 'infield-fundamentals';

INSERT INTO public.development_pathway_stage_drills (stage_id, drill_id, role, rank, rationale)
SELECT s.id, '2f3326af-9848-534e-9cc2-3d0f628c1162', 'primary', 1,
  'Deliberately rolls balls that cannot be fielded cleanly and does not let the rep end at the bobble. It is the only drill in the library built around the ball not doing what it should.'
FROM public.development_pathway_stages s
JOIN public.development_pathways p ON p.id = s.pathway_id
WHERE p.slug = 'infield-fundamentals' AND s.stage_key = 'reading-hops';
