SELECT p.id,
  6, 'funnel-transfer', 'Funnel and transfer',
  'Gets the ball from glove to throwing hand in one motion, in front of the chest.',
  'The exchange is where youth infielders lose the out. It is also the part nobody practises, because it looks like something that happens on its own.',
  ARRAY['Ball leaves the glove and reaches throwing position in one motion', 'Exchange happens in front of the chest, not below the waist', 'Four-seam grip more often than not, without looking at the hand'],
