VALUES (
  'outfield-development', 'Outfield Development', 'fielding',
  'Turning a player who stands still in the outfield into one who reads the ball, gets to it, catches it, and throws it to the right place.',
  'Assumes a player who can already catch a thrown ball; if not, run stages 3 and 4 first and treat the rest as later work. Stages 8 to 11 need Throwing Development stage 6 (footwork) to have landed.',
  7, 16, 1, 'published',
  'Phase 2E, 2026-09-17. Sequence written against the 154 schedulable drills as they stood at migration 068, using each row''s description, coaching notes, success markers and regression/progression notes as evidence. Not derived from progression_level, category, age or video order.'
);

-- stage 1: Ready position and first step
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  1, 'ready-and-first-step', 'Ready position and first step',
  'Is moving on contact rather than watching, with the first step taking ground.',
  'Almost all youth outfield practice sends a ball to a stationary player. Games do not, and the first step is where most of the ground is won or lost.',
  ARRAY['Runs a straight line to the spot rather than drifting in a curve', 'Glove comes up in the last two strides, not the first', 'Is already moving when the ball is caught rather than starting from still'],
  ARRAY['Standing flat and reacting after the ball has peaked', 'Bringing the glove up immediately, which slows the run', 'Drifting toward the ball instead of running to the spot and waiting'],
  NULL,
  1, 3,
  'THIN. There is no dedicated outfield ready-position drill in the library. "On the Run" covers the first step by implication because the player is already moving, and the drop-step drill covers it for balls hit overhead. Neither teaches the pre-pitch position itself. A short station — get into position on the pitch, react to a called direction — would close it.'
FROM public.development_pathways p WHERE p.slug = 'outfield-development';

INSERT INTO public.development_pathway_stage_drills (stage_id, drill_id, role, rank, rationale)
SELECT s.id, '07a59bb9-1b7c-554a-a1f1-98f4af671e21', 'primary', 1,
  'Starts the fielder moving before the ball is in the air and never hits it where they are standing, which is the whole difference between this and ordinary fly-ball work.'
FROM public.development_pathway_stages s
JOIN public.development_pathways p ON p.id = s.pathway_id
WHERE p.slug = 'outfield-development' AND s.stage_key = 'ready-and-first-step';
-- On the Run
INSERT INTO public.development_pathway_stage_drills (stage_id, drill_id, role, rank, rationale)
SELECT s.id, '744a47da-ef0c-42b0-b961-1175aaad42d9', 'reinforcement', 1,
  'Its mastery signals include the first step going back and opening the hips, so it doubles as first-step work before it becomes a drop-step stage.'
FROM public.development_pathway_stages s
JOIN public.development_pathways p ON p.id = s.pathway_id
WHERE p.slug = 'outfield-development' AND s.stage_key = 'ready-and-first-step';
