-- stage 3: Tracking a ball in the air
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  3, 'tracking', 'Tracking a ball in the air',
  'Keeps eyes on the ball into the glove and arrives set rather than still moving.',
  'A fielder still moving when the ball arrives is the one who drops it. Tracking is what buys the extra half-second to be set.',
  ARRAY['Eyes stay on the ball all the way into the glove', 'Arrives set under the ball with time to spare', 'Catches above the head rather than trapping it at the chest'],
  ARRAY['Head turning away in the last foot — a flinch, not a hands problem', 'Arriving late and catching on the move when there was time to set', 'Losing the ball against the sky and stopping rather than continuing the route'],
  NULL,
  2, 4,
  NULL
FROM public.development_pathways p WHERE p.slug = 'outfield-development';

