SELECT p.id,
  6, 'communication', 'Communication',
  'Calls the ball early and loudly, and yields audibly when called off.',
  'Two players who both go and neither calls is how a catchable ball lands between them — and how someone gets hurt.',
  ARRAY['Call comes before the ball peaks', 'Non-catching player audibly yields and peels off', 'No ball lands between two players across a full set'],
  ARRAY['Calling after the peak, when there is no time left to react', 'A silent peel-off, which looks identical to a player who has not seen it', 'Nobody calling at all and both players pulling up'],
  NULL,
